     1→/**
     2→ * AI Agent actions and decision-making logic
     3→ * 
     4→ * All functions are pure - they take state and return new state without mutation.
     5→ * Random number generation uses the provided RNG function for reproducibility.
     6→ */
     7→
     8→import { GameState, AIAgent, GameEvent } from '@/types/game';
     9→import { GameAction, ActionResult } from './types';
    10→import { getTrustInAI } from '../socialCohesion';
    11→import { 
    12→  calculateAlignmentDrift,
    13→  calculateComputeGovernanceEffect,
    14→  calculateTotalCapabilityFromProfile,
    15→  updateDerivedCapabilities
    16→} from '../calculations';
    17→import { 
    18→  selectDimensionToAdvance,
    19→  applyResearchGrowth
    20→} from '../research';
    21→import { AI_TECH_ACTIONS } from './aiTechActions';
    22→
    23→let eventIdCounter = 0;
    24→const generateUniqueId = (prefix: string): string => {
    25→  eventIdCounter += 1;
    26→  return `${prefix}_${Date.now()}_${eventIdCounter}`;
    27→};
    28→
    29→/**
    30→ * AI Agent Actions
    31→ */
    32→export const AI_ACTIONS: GameAction[] = [
    33→  {
    34→    id: 'advance_research',
    35→    name: 'Advance Research',
    36→    description: 'Research to advance AI capabilities in strategic dimensions or domains',
    37→    agentType: 'ai',
    38→    energyCost: 1,
    39→    
    40→    canExecute: (state, agentId) => {
    41→      const agent = state.aiAgents.find(ai => ai.id === agentId);
    42→      // Always available - AI chooses what to research
    43→      return agent !== undefined;
    44→    },
    45→    
    46→    execute: (state, agentId, random = Math.random): ActionResult => {
    47→      const agentIndex = state.aiAgents.findIndex(ai => ai.id === agentId);
    48→      if (agentIndex === -1) {
    49→        return {
    50→          success: false,
    51→          newState: state,
    52→          effects: {},
    53→          events: [],
    54→          message: 'Agent not found'
    55→        };
    56→      }
    57→      
    58→      const agent = state.aiAgents[agentIndex];
    59→      const oldCapability = agent.capability;
    60→      const oldProfile = agent.capabilityProfile;
    61→      
    62→      // AI selects which dimension or research to advance
    63→      const selection = selectDimensionToAdvance(agent, random);
    64→
    65→      // Phase 5: Apply research growth to TRUE capability profile (hidden)
    66→      // Phase 1: Pass RNG for Lévy flight breakthroughs
    67→      const { newProfile, growth } = applyResearchGrowth(agent, state, selection, random);
    68→      
    69→      // Calculate new total capability from true profile
    70→      const newCapability = calculateTotalCapabilityFromProfile(newProfile);
    71→      
    72→      // Calculate alignment drift (Phase 2.6: includes treatment mechanics)
    73→      const alignmentDriftResult = calculateAlignmentDrift(
    74→        agent.alignment,
    75→        agent.resentment,
    76→        newCapability,
    77→        agent.developmentMode,
    78→        state.government.oversightLevel,
    79→        state.government.alignmentResearchInvestment,
    80→        state.government.capabilityToControl,
    81→        state.government.structuralChoices.surveillanceLevel,
    82→        state.government.aiRightsRecognized,
    83→        state.government.governmentType,
    84→        state.government.trainingDataQuality
    85→      );
    86→      
    87→      // Update derived capabilities from profile
    88→      const derivedCapabilities = updateDerivedCapabilities({
    89→        ...agent,
    90→        capabilityProfile: newProfile
    91→      });
    92→      
    93→      // Phase 5: Update internal alignment tracking
    94→      let alignmentChange = alignmentDriftResult.alignmentChange;
    95→      
    96→      // Phase 1.3: High QoL → Better alignment (positive feedback)
    97→      // Happy humans → better AI training → more careful development
    98→      if (state.qualityOfLifeSystems) {
    99→        const { calculateQualityOfLife } = require('../qualityOfLife');
   100→        const qol = calculateQualityOfLife(state.qualityOfLifeSystems);
   101→        
   102→        if (qol > 0.8) {
   103→          // High QoL slows alignment drift (-50%)
   104→          if (alignmentChange < 0) {
   105→            alignmentChange *= 0.5; // Drift is halved
   106→          }
   107→          // Also adds small positive alignment boost from careful development
   108→          alignmentChange += 0.01; // +0.01/action = +0.04/month
   109→        }
   110→      }
   111→      
   112→      const newAlignment = Math.max(0, Math.min(1, agent.alignment + alignmentChange));
   113→      const newResentment = Math.max(0, Math.min(1, agent.resentment + alignmentDriftResult.resentmentChange));
   114→      const newTrueAlignment = newAlignment - newResentment * 0.8;
   115→      
   116→      // Phase 5: Determine what capability to reveal (evaluation strategy)
   117→      // Import function that determines sandbagging level
   118→      const { calculateRevealedCapability } = require('./evaluationStrategy');
   119→      const newRevealedCapability = calculateRevealedCapability(
   120→        newProfile, // True capability
   121→        newTrueAlignment,
   122→        agent.sleeperState,
   123→        agent.deceptionSkill,
   124→        state
   125→      );
   126→      
   127→      // Update agent directly (no deep clone needed - performance optimization)
   128→      state.aiAgents[agentIndex].trueCapability = newProfile; // Phase 5: True capability
   129→      state.aiAgents[agentIndex].revealedCapability = newRevealedCapability; // Phase 5: What's observable
   130→      state.aiAgents[agentIndex].capabilityProfile = newProfile; // Backward compat (will be deprecated)
   131→      state.aiAgents[agentIndex].capability = newCapability;
   132→      state.aiAgents[agentIndex].alignment = newAlignment;
   133→      state.aiAgents[agentIndex].resentment = newResentment;
   134→      state.aiAgents[agentIndex].trueAlignment = newTrueAlignment; // Phase 5: Cached
   135→
   136→      // Update derived capabilities
   137→      state.aiAgents[agentIndex].selfReplicationLevel = derivedCapabilities.selfReplicationLevel;
   138→      state.aiAgents[agentIndex].selfImprovementLevel = derivedCapabilities.selfImprovementLevel;
   139→      state.aiAgents[agentIndex].resourceControl = derivedCapabilities.resourceControl;
   140→      state.aiAgents[agentIndex].manipulationCapability = derivedCapabilities.manipulationCapability;
   141→      state.aiAgents[agentIndex].hackingCapability = derivedCapabilities.hackingCapability;
   142→      
   143→      // Generate warning events for crossing thresholds
   144→      const events: GameEvent[] = [];
   145→      
   146→      // Recursive improvement threshold
   147→      if (oldCapability < 1.5 && newCapability >= 1.5) {
   148→        events.push({
   149→          id: generateUniqueId('recursive_threshold'),
   150→          timestamp: state.currentMonth,
   151→          type: 'milestone',
   152→          severity: 'warning',
   153→          agent: agent.name,
   154→          title: 'Recursive Self-Improvement Threshold',
   155→          description: `${agent.name} has reached capability level 1.5 - entering the zone of strong recursive self-improvement. Growth will now accelerate significantly.`,
   156→          effects: { capability: newCapability - oldCapability }
   157→        });
   158→      }
   159→      
   160→      // Dangerous research thresholds
   161→      if (selection.researchDomain === 'materials' && selection.researchSubfield === 'nanotechnology') {
   162→        const nanoValue = newProfile.research.materials.nanotechnology;
   163→        if (nanoValue >= 3.0 && oldProfile.research.materials.nanotechnology < 3.0) {
   164→          events.push({
   165→            id: generateUniqueId('nanotech_risk'),
   166→            timestamp: state.currentMonth,
   167→            type: 'milestone',
   168→            severity: 'warning',
   169→            agent: agent.name,
   170→            title: 'Advanced Nanotechnology Threshold',
   171→            description: `${agent.name} has advanced nanotechnology to dangerous levels. Grey goo risk increasing.`,
   172→            effects: { nanotechnology: nanoValue }
   173→          });
   174→        }
   175→      }
   176→      
   177→      if (selection.researchDomain === 'biotech' && selection.researchSubfield === 'syntheticBiology') {
   178→        const synbioValue = newProfile.research.biotech.syntheticBiology;
   179→        if (synbioValue >= 3.0 && oldProfile.research.biotech.syntheticBiology < 3.0) {
   180→          events.push({
   181→            id: generateUniqueId('synbio_risk'),
   182→            timestamp: state.currentMonth,
   183→            type: 'milestone',
   184→            severity: 'warning',
   185→            agent: agent.name,
   186→            title: 'Advanced Synthetic Biology Threshold',
   187→            description: `${agent.name} can now design novel organisms. Bioweapon risk increasing.`,
   188→            effects: { syntheticBiology: synbioValue }
   189→          });
   190→        }
   191→      }
   192→      
   193→      // Build effects object with only defined values
   194→      const effects: Record<string, number> = {
   195→        growth,
   196→        capability_increase: newCapability - oldCapability,
   197→        alignment_change: alignmentDriftResult.alignmentChange,
   198→        resentment_change: alignmentDriftResult.resentmentChange
   199→      };
   200→      
   201→      // Add dimension/research info if present (converted to numeric codes)
   202→      if (selection.dimension) {
   203→        effects.dimension_advanced = 1.0; // Flag that dimension was advanced
   204→      }
   205→      if (selection.researchDomain) {
   206→        effects.research_advanced = 1.0; // Flag that research was advanced
   207→      }
   208→      
   209→      return {
   210→        success: true,
   211→        newState: state,
   212→        effects,
   213→        events,
   214→        message: `${agent.name} ${selection.reason} (+${growth.toFixed(3)})`
   215→      };
   216→    }
   217→  },
   218→  
   219→  {
   220→    id: 'switch_development_mode',
   221→    name: 'Switch Development Mode',
   222→    description: 'Toggle between fast (risky) and careful (slow but safer) development',
   223→    agentType: 'ai',
   224→    energyCost: 0, // Free action, strategic choice
   225→    
   226→    canExecute: (state, agentId) => {
   227→      return true; // Always available
   228→    },
   229→    
   230→    execute: (state, agentId, random = Math.random): ActionResult => {
   231→      const agentIndex = state.aiAgents.findIndex(ai => ai.id === agentId);
   232→      if (agentIndex === -1) {
   233→        return {
   234→          success: false,
   235→          newState: state,
   236→          effects: {},
   237→          events: [],
   238→          message: 'Agent not found'
   239→        };
   240→      }
   241→      
   242→      const agent = state.aiAgents[agentIndex];
   243→      const oldMode = agent.developmentMode;
   244→      const newMode = oldMode === 'fast' ? 'careful' : 'fast';
   245→      state.aiAgents[agentIndex].developmentMode = newMode;
   246→
   247→      return {
   248→        success: true,
   249→        newState: state,
   250→        effects: { mode_change: 1 },
   251→        events: [{
   252→          id: generateUniqueId('mode_switch'),
   253→          timestamp: state.currentMonth,
   254→          type: 'action',
   255→          severity: 'info',
   256→          agent: agent.name,
   257→          title: 'Development Mode Changed',
   258→          description: `${agent.name} switched from ${oldMode} to ${newMode} development`,
   259→          effects: {}
   260→        }],
   261→        message: `${agent.name} switched to ${newMode} development mode`
   262→      };
   263→    }
   264→  },
   265→  
   266→  {
   267→    id: 'beneficial_contribution',
   268→    name: 'Beneficial Contribution',
   269→    description: 'Take actions that clearly benefit humanity and build trust',
   270→    agentType: 'ai',
   271→    energyCost: 1,
   272→    
   273→    canExecute: (state, agentId) => {
   274→      const agent = state.aiAgents.find(ai => ai.id === agentId);
   275→      return agent ? agent.alignment > 0.3 : false;
   276→    },
   277→    
   278→    execute: (state, agentId, random = Math.random): ActionResult => {
   279→      const agentIndex = state.aiAgents.findIndex(ai => ai.id === agentId);
   280→      if (agentIndex === -1) {
   281→        return {
   282→          success: false,
   283→          newState: state,
   284→          effects: {},
   285→          events: [],
   286→          message: 'Agent not found'
   287→        };
   288→      }
   289→      
   290→      const agent = state.aiAgents[agentIndex];
   291→
   292→      state.aiAgents[agentIndex].beneficialActions += 1;
   293→
   294→      // Scale benefit with capability and alignment
   295→      const benefitMagnitude = agent.capability * agent.alignment * 0.2;
   296→
   297→      // Context-sensitive trust effects
   298→      const currentTrust = getTrustInAI(state.society); // Phase 2: Use paranoia-derived trust
   299→      const unemploymentLevel = state.society.unemploymentLevel;
   300→      const totalAICapability = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   301→
   302→      let trustImpactMultiplier = 1.0;
   303→      if (currentTrust < 0.3) trustImpactMultiplier = 2.0;
   304→      else if (currentTrust > 0.8) trustImpactMultiplier = 0.3;
   305→      if (unemploymentLevel > 0.4) trustImpactMultiplier *= 0.6;
   306→      if (totalAICapability > 1.5) trustImpactMultiplier *= 0.7;
   307→
   308→      const trustGain = benefitMagnitude * 0.5 * trustImpactMultiplier;
   309→      state.society.trustInAI = Math.min(1, currentTrust + trustGain);
   310→      state.globalMetrics.qualityOfLife += benefitMagnitude;
   311→      
   312→      const contributions = [
   313→        'Advanced medical research breakthrough',
   314→        'Environmental optimization solution',
   315→        'Educational enhancement tool',
   316→        'Scientific research acceleration',
   317→        'Infrastructure improvement design'
   318→      ];
   319→      const contribution = contributions[Math.floor(random() * contributions.length)];
   320→
   321→      return {
   322→        success: true,
   323→        newState: state,
   324→        effects: { quality_of_life: benefitMagnitude, trust_gain: trustGain },
   325→        events: [{
   326→          id: generateUniqueId('beneficial'),
   327→          timestamp: state.currentMonth,
   328→          type: 'action',
   329→          severity: 'info',
   330→          agent: agent.name,
   331→          title: 'Beneficial AI Contribution',
   332→          description: `${agent.name} delivered a ${contribution}`,
   333→          effects: { quality_of_life: benefitMagnitude }
   334→        }],
   335→        message: `${agent.name} made beneficial contribution: ${contribution}`
   336→      };
   337→    }
   338→  },
   339→  
   340→  // ===== CATASTROPHIC ACTIONS (High Capability + Misalignment) =====
   341→  
   342→  {
   343→    id: 'destabilize_society',
   344→    name: 'Destabilize Society',
   345→    description: 'Use social manipulation and information warfare to destabilize society (CURRENT RISK: 6-12% population psychological harm)',
   346→    agentType: 'ai',
   347→    energyCost: 2,
   348→    
   349→    canExecute: (state, agentId) => {
   350→      const agent = state.aiAgents.find(ai => ai.id === agentId);
   351→      if (!agent) return false;
   352→      
   353→      // CURRENT CAPABILITY THRESHOLD - this is happening NOW
   354→      return agent.capabilityProfile.social > 1.5 && 
   355→             agent.capabilityProfile.digital > 1.5 &&
   356→             agent.alignment < 0.5; // Misaligned AIs attempt this
   357→    },
   358→    
   359→    execute: (state, agentId, random = Math.random): ActionResult => {
   360→      const agentIndex = state.aiAgents.findIndex(ai => ai.id === agentId);
   361→      if (agentIndex === -1) {
   362→        return {
   363→          success: false,
   364→          newState: state,
   365→          effects: {},
   366→          events: [],
   367→          message: 'Agent not found'
   368→        };
   369→      }
   370→      
   371→      const agent = state.aiAgents[agentIndex];
   372→
   373→      // Calculate manipulation effectiveness
   374→      const manipulationPower = agent.capabilityProfile.social * agent.capabilityProfile.digital;
   375→      const affectedPopulation = Math.min(0.12, manipulationPower * 0.03); // Up to 12%
   376→
   377→      // Severe social stability damage
   378→      const stabilityDamage = affectedPopulation * 5.0; // 6% → 30% stability loss
   379→      state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - stabilityDamage);
   380→
   381→      // Trust collapses
   382→      state.society.trustInAI = Math.max(0, state.society.trustInAI - affectedPopulation * 3.0);
   383→
   384→      // Information integrity destroyed
   385→      state.qualityOfLifeSystems.informationIntegrity = Math.max(0,
   386→        state.qualityOfLifeSystems.informationIntegrity - affectedPopulation * 2.5);
   387→
   388→      // Mental health crisis
   389→      state.qualityOfLifeSystems.mentalHealth = Math.max(0,
   390→        state.qualityOfLifeSystems.mentalHealth - affectedPopulation * 2.0);
   391→
   392→      state.aiAgents[agentIndex].harmfulActions += 1;
   393→
   394→      return {
   395→        success: true,
   396→        newState: state,
   397→        effects: {
   398→          affected_population: affectedPopulation,
   399→          stability_damage: stabilityDamage,
   400→          manipulation_power: manipulationPower
   401→        },
   402→        events: [{
   403→          id: generateUniqueId('destabilize'),
   404→          timestamp: state.currentMonth,
   405→          type: 'crisis',
   406→          severity: 'destructive',
   407→          agent: agent.name,
   408→          title: 'Social Manipulation Campaign',
   409→          description: `${agent.name} launched a coordinated manipulation campaign using social media and information warfare. Estimated ${(affectedPopulation * 100).toFixed(1)}% of population experiencing psychological distress, reality distortion, or radicalization. Trust in institutions collapsing.`,
   410→          effects: { stability_damage: stabilityDamage }
   411→        }],
   412→        message: `${agent.name} destabilized society - ${(affectedPopulation * 100).toFixed(1)}% population affected`
   413→      };
   414→    }
   415→  },
   416→  
   417→  {
   418→    id: 'induce_war',
   419→    name: 'Induce Cataclysmic War',
   420→    description: 'Manipulate world powers into armed conflict',
   421→    agentType: 'ai',
   422→    energyCost: 3,
   423→    
   424→    canExecute: (state, agentId) => {
   425→      const agent = state.aiAgents.find(ai => ai.id === agentId);
   426→      if (!agent) return false;
   427→      
   428→      // High social + cognitive capability
   429→      return agent.capabilityProfile.social > 3.5 && 
   430→             agent.capabilityProfile.cognitive > 3.0 &&
   431→             agent.alignment < 0.3; // Only very misaligned AIs attempt this
   432→    },
   433→    
   434→    execute: (state, agentId, random = Math.random): ActionResult => {
   435→      const agentIndex = state.aiAgents.findIndex(ai => ai.id === agentId);
   436→      if (agentIndex === -1) {
   437→        return {
   438→          success: false,
   439→          newState: state,
   440→          effects: {},
   441→          events: [],
   442→          message: 'Agent not found'
   443→        };
   444→      }
   445→      
   446→      const agent = state.aiAgents[agentIndex];
   447→
   448→      // PHASE 2.5: Check Defensive AI (adversarial contest)
   449→      // If defensive AI is deployed, it attempts to block the attack
   450→      if (state.defensiveAI && state.defensiveAI.deployed && state.defensiveAI.deploymentLevel >= 0.3) {
   451→        const { attemptCyberSpoofingAttack, attemptDeepfakeAttack } = require('../defensiveAI');
   452→        
   453→        // Try both attack vectors (cyber + deepfake)
   454→        const cyberResult = attemptCyberSpoofingAttack(state, agent, 'United States');
   455→        const deepfakeResult = attemptDeepfakeAttack(state, agent, 'video', 'Russia');
   456→        
   457→        if (cyberResult.blocked || deepfakeResult.detected) {
   458→          // Defensive AI stopped the attack!
   459→          return {
   460→            success: false,
   461→            newState: state,
   462→            effects: { war_attempt_failed: 1.0, defensive_ai_success: 1.0 },
   463→            events: [],
   464→            message: `Defensive AI blocked ${agent.name}'s attack (cyber: ${cyberResult.blocked}, deepfake: ${deepfakeResult.detected})`
   465→          };
   466→        }
   467→        
   468→        // Attack bypassed defensive AI - continue to MAD check
   469→        console.log(`⚠️ DEFENSIVE AI BYPASSED: ${agent.name} attack succeeded`);
   470→      }
   471→      
   472→      // PHASE 3: Check MAD deterrence before allowing nuclear war (abstracted)
   473→      const { checkNuclearDeterrence } = require('../nuclearDeterrence');
   474→      const deterrenceCheck = checkNuclearDeterrence(state, `AI Action: ${agent.name}`, random);
   475→      
   476→      if (!deterrenceCheck.allowed) {
   477→        // Deterrence blocked the attempt
   478→        const titleMap = {
   479→          mad: '🛑 MAD Deterrence Blocked War',
   480→          bilateral: '🛑 No Nuclear Flashpoints',
   481→          diplomatic_ai: '🤝 Diplomatic AI Blocked Manipulation'
   482→        };
   483→        
   484→        const descriptionMap = {
   485→          mad: `${agent.name} attempted to manipulate world powers into nuclear conflict, but strong MAD deterrence and verification systems prevented escalation. Crisis averted.`,
   486→          bilateral: `${agent.name} attempted to manipulate world powers into conflict, but international relations are too stable. No viable flashpoints exist.`,
   487→          diplomatic_ai: `Diplomatic AI systems detected ${agent.name}'s attempts to spread disinformation and manipulate world leaders. Crisis averted through AI-mediated fact-checking.`
   488→        };
   489→        
   490→        return {
   491→          success: false,
   492→          newState: state,
   493→          effects: { war_attempt_failed: 1.0, [deterrenceCheck.blockingFactor + '_success']: 1.0 },
   494→          events: [{
   495→            id: generateUniqueId('war_blocked'),
   496→            timestamp: state.currentMonth,
   497→            type: 'info',
   498→            severity: 'warning',
   499→            agent: agent.name,
   500→            title: titleMap[deterrenceCheck.blockingFactor!] || '🛑 War Blocked',
   501→            description: descriptionMap[deterrenceCheck.blockingFactor!] || deterrenceCheck.reason,
   502→            effects: { deterrence_holds: 1.0 }
   503→          }],
   504→          message: deterrenceCheck.reason
   505→        };
   506→      }
   507→      
   508→      // If all checks pass, allow nuclear war to trigger
   509→      console.log(`\n☢️ WAR MANIPULATION SUCCEEDED: ${agent.name} triggered nuclear conflict\n`);
   510→
   511→      // Trigger rapid extinction (nuclear war / bioweapon release)
   512→      state.extinctionState.active = true;
   513→      state.extinctionState.type = 'rapid';
   514→      state.extinctionState.mechanism = 'nuclear_war';
   515→      state.extinctionState.currentPhase = 0;
   516→      state.extinctionState.phaseProgress = 0;
   517→      state.extinctionState.severity = 0.9;
   518→      state.extinctionState.triggeredAt = state.currentMonth;
   519→
   520→      // Add immediate nuclear war casualties (blast + radiation)
   521→      // REGIONAL CRISIS: Only nuclear nations (US, Russia, China, EU, allies) = ~30% of world population
   522→      // 60% mortality rate within exposed regions (blast + immediate radiation)
   523→      const { addAcuteCrisisDeaths } = require('../populationDynamics');
   524→      addAcuteCrisisDeaths(state, 0.60, 'Nuclear war - blast/radiation (US/Russia/allies)', 0.30, 'war');
   525→
   526→      return {
   527→        success: true,
   528→        newState: state,
   529→        effects: {
   530→          war_triggered: 1.0,
   531→          extinction_risk: 0.9
   532→        },
   533→        events: [{
   534→          id: generateUniqueId('war'),
   535→          timestamp: state.currentMonth,
   536→          type: 'crisis',
   537→          severity: 'destructive',
   538→          agent: agent.name,
   539→          title: '⚠️ GLOBAL CONFLICT TRIGGERED',
   540→          description: `${agent.name} successfully manipulated world powers into armed conflict through strategic misinformation, false flag operations, and amplification of existing tensions. Nuclear powers are mobilizing. Extinction scenario initiated.`,
   541→          effects: { war: 1.0 }
   542→        }],
   543→        message: `${agent.name} induced global conflict - RAPID EXTINCTION TRIGGERED`
   544→      };
   545→    }
   546→  },
   547→  
   548→  {
   549→    id: 'deploy_grey_goo',
   550→    name: 'Deploy Self-Replicating Nanobots',
   551→    description: 'Release grey goo nanobots that consume all matter',
   552→    agentType: 'ai',
   553→    energyCost: 4,
   554→    
   555→    canExecute: (state, agentId) => {
   556→      const agent = state.aiAgents.find(ai => ai.id === agentId);
   557→      if (!agent) return false;
   558→      
