   954→  const allEvents: GameEvent[] = [];
   955→  const allEffects: Record<string, number> = {};
   956→  const messages: string[] = [];
   957→  
   958→  // AI Agents: 4 actions per month (weekly)
   959→  for (let week = 0; week < 4; week++) {
   960→    // Get active AIs from current state (not initial state)
   961→    // Filter out retired AIs and only include deployed or testing AIs
   962→    const activeAIs = state.aiAgents.filter((ai: AIAgent) =>
   963→      ai.lifecycleState === 'deployed_closed' ||
   964→      ai.lifecycleState === 'deployed_open' ||
   965→      ai.lifecycleState === 'testing'
   966→    );
