   972→        if (result.success) {
   973→          // Actions mutate state directly, no need to reassign
   974→          allEvents.push(...result.events);
   975→          Object.assign(allEffects, result.effects);
   976→          messages.push(result.message);
   977→        }
   978→      }
   979→    }
   980→  }
