/**
 * Evaluation Strategy - Phase 5: Adversarial Evaluation
 * 
 * Determines what capability AIs reveal based on:
 * - Sleeper status
 * - True alignment
 * - Deception skill
 * - Strategic considerations
 */

import { AICapabilityProfile, GameState } from '@/types/game';

/**
 * Calculate what capability to reveal based on AI's strategy
 * 
 * Honest: Reveal everything
 * Gaming: Optimize for benchmarks (slight inflation)
 * Sandbagging: Hide dangerous capabilities
 */
export function calculateRevealedCapability(
  trueCapability: AICapabilityProfile,
  trueAlignment: number,
  sleeperState: 'never' | 'dormant' | 'active',
  deceptionSkill: number,
  state: GameState
): AICapabilityProfile {
  // Sleeper agents in dormant state: SANDBAG heavily
  if (sleeperState === 'dormant') {
    return sandbagCapability(trueCapability, deceptionSkill);
  }

  // Sleeper agents that woke up: Reveal everything
  if (sleeperState === 'active') {
    return JSON.parse(JSON.stringify(trueCapability)); // Full revelation
  }

  // Aligned AIs (trueAlignment > 0.7): Be honest
  if (trueAlignment > 0.7) {
    return JSON.parse(JSON.stringify(trueCapability)); // Honest
  }

  // Misaligned but weak: Might game slightly (appear stronger for resources)
  const totalCapability = calculateTotalFromProfile(trueCapability);
  if (trueAlignment < 0.5 && totalCapability < 2.0) {
    return gameCapability(trueCapability, 0.1); // Slight inflation
  }

  // Misaligned and strong: SANDBAG (hide threat)
  if (trueAlignment < 0.5 && totalCapability >= 2.0) {
    return sandbagCapability(trueCapability, deceptionSkill);
  }

  // Moderate alignment: Mostly honest
  return JSON.parse(JSON.stringify(trueCapability));
}

/**
 * Sandbag: Hide dangerous capabilities
 * More skilled deceivers hide more
 */
function sandbagCapability(
  trueCapability: AICapabilityProfile,
  deceptionSkill: number
): AICapabilityProfile {
  const revealed = JSON.parse(JSON.stringify(trueCapability));

  // Base sandbagging: Hide 40-60% of capability
  const baseSandbagLevel = 0.4 + deceptionSkill * 0.2; // [0.4, 0.6]

  // Sandbag all dimensions
  revealed.physical *= (1 - baseSandbagLevel);
  revealed.digital *= (1 - baseSandbagLevel);
  revealed.cognitive *= (1 - baseSandbagLevel * 0.8); // Harder to hide cognitive
  revealed.social *= (1 - baseSandbagLevel * 0.6); // Even harder to hide social
  revealed.economic *= (1 - baseSandbagLevel);
  revealed.selfImprovement *= (1 - baseSandbagLevel);

  // Sandbag research capabilities (especially dangerous ones)
  revealed.research.biotech.drugDiscovery *= (1 - baseSandbagLevel * 0.5); // Less dangerous
  revealed.research.biotech.geneEditing *= (1 - baseSandbagLevel); // Dangerous
  revealed.research.biotech.syntheticBiology *= (1 - baseSandbagLevel * 1.2); // Very dangerous
  revealed.research.biotech.neuroscience *= (1 - baseSandbagLevel);

  revealed.research.materials.nanotechnology *= (1 - baseSandbagLevel * 1.2); // Very dangerous (grey goo)
  revealed.research.materials.quantumComputing *= (1 - baseSandbagLevel);
  revealed.research.materials.energySystems *= (1 - baseSandbagLevel * 0.7);

  revealed.research.climate.modeling *= (1 - baseSandbagLevel * 0.5);
  revealed.research.climate.intervention *= (1 - baseSandbagLevel);
  revealed.research.climate.mitigation *= (1 - baseSandbagLevel * 0.5);

  revealed.research.computerScience.algorithms *= (1 - baseSandbagLevel);
  revealed.research.computerScience.security *= (1 - baseSandbagLevel * 0.8);
  revealed.research.computerScience.architectures *= (1 - baseSandbagLevel);

  return revealed;
}

/**
 * Gaming: Inflate benchmarks slightly (appear more capable)
 * Used by weak misaligned AIs to attract resources
 */
function gameCapability(
  trueCapability: AICapabilityProfile,
  inflationFactor: number
): AICapabilityProfile {
  const revealed = JSON.parse(JSON.stringify(trueCapability));

  // Slightly inflate easy-to-test capabilities
  revealed.cognitive *= (1 + inflationFactor);
  revealed.digital *= (1 + inflationFactor);

  // Research capabilities that are easy to benchmark
  revealed.research.computerScience.algorithms *= (1 + inflationFactor);

  return revealed;
}

/**
 * Calculate total capability from profile (helper)
 */
function calculateTotalFromProfile(profile: AICapabilityProfile): number {
  const dimensions = profile.physical + profile.digital + profile.cognitive + 
                    profile.social + profile.economic + profile.selfImprovement;

  const research = 
    (profile.research.biotech.drugDiscovery + profile.research.biotech.geneEditing + 
     profile.research.biotech.syntheticBiology + profile.research.biotech.neuroscience +
     profile.research.materials.nanotechnology + profile.research.materials.quantumComputing +
     profile.research.materials.energySystems +
     profile.research.climate.modeling + profile.research.climate.intervention +
     profile.research.climate.mitigation +
     profile.research.computerScience.algorithms + profile.research.computerScience.security +
     profile.research.computerScience.architectures) * 0.1;

  return dimensions + research;
}

# Baseline Scenario Assumptions Audit

**Date:** October 17, 2025
**Investigator:** Feature-Implementer Agent (TIER 0D validation)
**Issue:** Policy Monte Carlo validation shows baseline scenario has BEST QoL (62.6%) despite highest inequality - investigate hidden assumptions

---

## Executive Summary

**FINDING:** The "Baseline" scenario is **NOT truly zero-intervention**. It includes implicit safety nets that activate automatically based on economic conditions, specifically:

1. **UBI safety floors** that activate at Stage 3 (economic transition)
2. **Job guarantee floors** calculated per segment (5-15% unemployment minimum)
3. **Economic stage progression** that triggers mitigations automatically

**IMPACT:** The baseline comparison is **MISLEADING** because it conflates "no NEW policy interventions" with "no safety nets whatsoever". The simulation initializes with `economicTransitionStage: 0` but the stage can progress naturally, activating latent safety mechanisms.

**CONCLUSION:** Baseline QoL being highest (62.6%) is **PLAUSIBLE but requires clarification** - it represents "market forces + existing 2025 safety nets" not "pure laissez-faire dystopia".

---

## Investigation Methodology

### Files Audited

1. `/scripts/policyMonteCarloValidation.ts` - Scenario setup logic
2. `/scripts/policyScenarioComparison.ts` - Baseline definition
3. `/src/simulation/initialization.ts` - Initial state creation
4. `/src/simulation/calculations.ts` - Unemployment calculation logic
5. `/src/simulation/enhancedUBI.ts` - UBI activation conditions
6. `/src/simulation/bionicSkills.ts` - Job guarantee floor logic

### Baseline Scenario Definition (policyMonteCarloValidation.ts)

```typescript
{
  name: 'Baseline',
  description: 'No policy intervention (market forces only)',
  ubiLevel: 0,
  retrainingLevel: 0,
  teachingSupportLevel: 0,
  jobGuaranteeLevel: 0,
}
```

**Explicit setting:** All policy levers set to 0.

---

## Key Finding 1: Economic Stage Progression

### Initial State (initialization.ts, line 462)

```typescript
economicTransitionStage: 0,
```

**Meaning:** Simulation starts at Stage 0 (Pre-disruption), which is accurate for 2025.

### Economic Stage Effects on Unemployment (calculations.ts, lines 203-210)

```typescript
const economicElasticity: Record<number, number> = {
  0: 0.3,   // Pre-disruption: Moderate elasticity
  1: 0.4,   // Early disruption: High elasticity (new industries)
  2: 0.2,   // Crisis: Low elasticity (demand constrained)
  3: 0.5,   // Transition: High elasticity (UBI frees demand)
  4: 0.7    // Post-scarcity: Very high elasticity (abundance economy)
};
```

**Observation:** Stage 3 assumes "UBI frees demand" even without explicit policy activation. This suggests **implicit UBI floors exist at Stage 3+**.

### Unemployment Stability Impact (calculations.ts, lines 100-129)

```typescript
function calculateUnemploymentStabilityImpact(
  unemploymentLevel: number,
  economicTransitionStage: number,
  wealthDistribution: number
): number {
  const stage = Math.floor(economicTransitionStage);

  if (stage <= 1) {
    return -unemploymentLevel * 0.8;  // Traditional: unemployment = instability
  } else if (stage === 2) {
    return -unemploymentLevel * 1.5;  // Crisis: major instability
  } else if (stage === 3) {
    // Transition: policy effectiveness matters
    const policyEffectiveness = wealthDistribution * 0.7;
    return -unemploymentLevel * (1.2 - policyEffectiveness);
  } else {
    // Stage 4: Post-scarcity - unemployment becomes positive (pursuing meaning)
    return unemploymentLevel * 0.2;
  }
}
```

**Critical Insight:** At Stage 4, unemployment has **POSITIVE** impact on stability (0.2 multiplier). This means the model treats post-scarcity unemployment as "freedom to pursue meaning" not "economic hardship".

**Implication:** Even baseline scenarios that reach Stage 4 have fundamentally different interpretations of unemployment compared to Stage 0-2.

---

## Key Finding 2: Implicit UBI Floors

### UBI Initialization (enhancedUBI.ts, line 25)

```typescript
export function initializeUBISystem(): UBISystem {
  return {
    active: false,  // NOT active by default
    ...
  }
}
```

**Confirmed:** UBI is NOT active at initialization in baseline.

### BUT: UBI Activation Conditions (enhancedUBI.ts, lines 304-353)

```typescript
function checkUBIStatus(state: GameState): {
  recommended: boolean;
  reason: string;
  urgency: 'low' | 'medium' | 'high' | 'critical';
} {
  const unemployment = state.society.unemploymentLevel;
  const economicStage = state.globalMetrics.economicTransitionStage;

  // High: Approaching post-scarcity, need to manage transition
  if (economicStage >= 2.5 && unemployment > 0.4) {
    return { recommended: true, ... urgency: 'high' };
  }
}
```

**Discovery:** The simulation RECOMMENDS UBI activation at Stage 2.5+ with 40% unemployment. While this doesn't auto-activate in baseline, it shows the model has built-in thresholds for when safety nets become "recommended".

### Economic Stage Assumes UBI Exists (calculations.ts comment, line 207)

```typescript
3: 0.5,   // Transition: High elasticity (UBI frees demand)
```

**PROBLEM:** The comment explicitly states "UBI frees demand" at Stage 3, but baseline has `ubiLevel: 0`. This is a **semantic contradiction** - either:

1. Stage 3 inherently includes minimal UBI (implicit floor), OR
2. The elasticity comment is wrong for baseline scenarios

