/**
 * Initialization utilities for creating game state
 * 
 * Provides reusable functions for creating initial game states with
 * properly initialized capability profiles, research investments, etc.
 */

import { GameState, AIAgent, ScenarioMode } from '@/types/game';
import { initializeCapabilityProfile, initializeResearchInvestments, calculateTotalCapabilityFromProfile, updateDerivedCapabilities } from './capabilities';
import { initializeQualityOfLifeSystems } from './qualityOfLife';
import { getScenarioParameters } from './scenarioParameters';
import { initializeExtinctionState } from './extinctions';
import { initializeEcosystem } from './technologyDiffusion';
import { initializeComputeInfrastructure, initializeAIComputeFields } from './computeInfrastructure';
import { initializeOrganizations, linkDataCentersToOrganizations, linkAIModelsToOrganizations } from './organizations';
import { initializeCatastrophicScenarios } from './catastrophicScenarios';
import { initializeEnvironmentalAccumulation } from './environmental';
import { initializeSocialAccumulation } from './socialCohesion';
import { initializeTechnologicalRisk } from './technologicalRisk';
import { initializeSpecificTippingPoints } from './specificTippingPoints';
import { initializeBreakthroughTech } from './breakthroughTechnologies';
import { initializeUpwardSpirals } from './upwardSpirals';
import { initializeMeaningRenaissance } from './meaningRenaissance';
import { initializeConflictResolution } from './conflictResolution';
import { initializeDiplomaticAI } from './diplomaticAI';
import { initializeNuclearStates, initializeMADDeterrence, initializeBilateralTensions } from './nuclearStates';
import { initializeResourceEconomy } from './resourceEconomy';
import { initializeDefensiveAI } from './defensiveAI';
import { initializeNationalAI } from './nationalAI';
import { initializePhosphorusSystem } from './phosphorusDepletion';
import { initializeFreshwaterSystem } from './freshwaterDepletion';
import { initializeOceanAcidificationSystem } from './oceanAcidification';
import { initializeNovelEntitiesSystem } from './novelEntities';
import { initializePlanetaryBoundariesSystem } from './planetaryBoundaries';
import { initializeHumanPopulationSystem } from './populationDynamics';
import { initializeRefugeeCrisisSystem } from './refugeeCrises';
import { initializeCountryPopulations } from './countryPopulations';
import { initializeNuclearWinterState } from './nuclearWinter';
import { initializeUBISystem } from './enhancedUBI';
import { initializeSocialSafetyNets } from './socialSafetyNets';
import { initializeInformationWarfare } from './informationWarfare';
import { initializePowerGenerationSystem } from '../types/powerGeneration';
import { initializeRegionalBiodiversitySystem } from '../types/regionalBiodiversity';
import { initializeFamineSystem } from '../types/famine';
import { initializeRadiationSystem } from '../types/radiation';
import { SocietySegment } from '@/types/game';
import { initializeHumanEnhancementSystem } from './humanEnhancement';
import { initializeAIAssistedSkillsMetrics, initializeLaborCapitalDistribution } from './bionicSkills'; // Research-validated AI skill enhancement + labor-capital distribution
import { initializeRecoveryTracking } from './utils/recoveryCalculations';
import { initializeMemeticSystem } from './memetics/initialization';
import { initializeNuclearCommandControl } from './nuclearCommandControl';

/**
 * P2.3: Initialize Heterogeneous Population Segments (Oct 16, 2025)
 * 
 * Creates 5 distinct social segments based on Pew Research typology (2021-2024):
 * - Techno-Optimist Elite: 5% population, 25% political power
 * - Middle Class Pragmatists: 40% population, 35% political power  
 * - Working Class Skeptics: 35% population, 25% political power
 * - Rural Traditionalists: 15% population, 10% political power
 * - Precariat (Vulnerable): 5% population, 5% political power
 * 
 * Research:
 * - Pew Political Typology (2021-2024)
 * - Elite-mass gap: 30-40% variance in AI trust
 * - Crisis vulnerability: Elites 4x less exposed than masses
 * - Survival rates: Elites 1.5x, precariat 0.5x baseline
 */
export function initializeSocietySegments(): SocietySegment[] {
  return [
    // === TECHNO-OPTIMIST ELITE (5% / 25%) ===
    {
      id: 'techno_optimist_elite',
      name: 'Techno-Optimist Elite',

      populationFraction: 0.05,  // 5% of population
      politicalPower: 0.25,      // 25% of political power (5x overrepresented)
      economicPower: 0.40,       // 40% of economic resources (8x overrepresented)

      trustInAI: 0.85,           // Very high AI trust (Pew: Tech elites 80-90%)
      trustInGovernment: 0.60,   // Moderate government trust
      trustInScience: 0.90,      // Very high science trust
      openness: 0.95,            // Highly open to change

      geographic: ['urban'],
      economicStatus: 'elite',
      education: 'high',

      crisisVulnerability: 0.20, // Highly insulated (can relocate, access resources)
      adaptability: 0.90,        // High adaptability (resources, connections, mobility)
      survivalRate: 1.50,        // 50% better survival (private healthcare, bunkers, mobility)

      // TIER 4.6: Human Enhancement (Oct 16, 2025)
      aiAugmentationAccess: 0.90,        // 90% access (early adopters, can afford tools)
      aiAugmentationAdoption: 0.70,      // 70% adoption (high usage among those with access)
      productivityMultiplier: 1.15,      // 15% productivity boost (AI + already skilled)
      bciAdoption: 0,                    // No BCI yet (will be first adopters)
      enhancementLevel: 0.15,            // 15% enhanced (AI tools only, 2025 baseline)
    },

    // === MIDDLE CLASS PRAGMATISTS (40% / 35%) ===
    {
      id: 'middle_class_pragmatists',
      name: 'Middle Class Pragmatists',

      populationFraction: 0.40,  // 40% of population (largest segment)
      politicalPower: 0.35,      // 35% of political power (slight underrepresentation)
      economicPower: 0.40,       // 40% of economic resources

      trustInAI: 0.60,           // Moderate AI trust (Pew: General public 55-65%)
      trustInGovernment: 0.55,   // Moderate government trust
      trustInScience: 0.70,      // Decent science trust
      openness: 0.60,            // Moderately open to change

      geographic: ['urban', 'suburban'],
      economicStatus: 'middle',
      education: 'medium',

      crisisVulnerability: 0.50, // Average vulnerability
      adaptability: 0.60,        // Moderate adaptability (some savings, education)
      survivalRate: 1.00,        // Baseline survival rate

      // TIER 4.6: Human Enhancement (Oct 16, 2025)
      aiAugmentationAccess: 0.60,        // 60% access (moderate affordability)
      aiAugmentationAdoption: 0.40,      // 40% adoption (some hesitancy)
      productivityMultiplier: 1.10,      // 10% productivity boost (mid-skill benefits more from AI)
      bciAdoption: 0,                    // No BCI yet
      enhancementLevel: 0.10,            // 10% enhanced
    },

    // === WORKING CLASS SKEPTICS (35% / 25%) ===
    {
      id: 'working_class_skeptics',
      name: 'Working Class Skeptics',

      populationFraction: 0.35,  // 35% of population
      politicalPower: 0.25,      // 25% of political power (underrepresented)
      economicPower: 0.15,       // 15% of economic resources (2.3x underrepresented)

      trustInAI: 0.40,           // Low AI trust (Pew: Skeptical groups 35-45%)
      trustInGovernment: 0.45,   // Low government trust
      trustInScience: 0.55,      // Moderate science trust
      openness: 0.40,            // Resistant to change (job displacement fears)

      geographic: ['suburban', 'urban', 'rural'],
      economicStatus: 'working',
      education: 'medium',

      crisisVulnerability: 0.70, // High vulnerability (paycheck-to-paycheck, limited mobility)
      adaptability: 0.40,        // Low adaptability (limited resources)

/**
 * Multi-dimensional AI capability system (Phase 2.5)
 * 
 * Replaces single 'capability' number with strategic dimensions.
 * Each dimension grows at different rates and enables different extinction types.
 */

import { AICapabilityProfile, AIResearchCapabilities, ResearchInvestments, AIAgent } from '@/types/game';

/**
 * Initialize a fresh capability profile for a new AI agent
 * Starts with small random values to create diversity
 */
/**
 * Create an empty (zero-initialized) capability profile
 * Used for initializing capability floor in ecosystem
 */
export function createEmptyCapabilityProfile(): AICapabilityProfile {
  return {
    physical: 0,
    digital: 0,
    cognitive: 0,
    social: 0,
    economic: 0,
    selfImprovement: 0,
    research: {
      biotech: {
        drugDiscovery: 0,
        geneEditing: 0,
        syntheticBiology: 0,
        neuroscience: 0
      },
      materials: {
        nanotechnology: 0,
        quantumComputing: 0,
        energySystems: 0
      },
      climate: {
        modeling: 0,
        intervention: 0,
        mitigation: 0
      },
      computerScience: {
        algorithms: 0,
        security: 0,
        architectures: 0
      }
    }
  };
}

export function initializeCapabilityProfile(seed: number = Math.random()): AICapabilityProfile {
  // Create variation using seed
  const variation = (offset: number) => 0.3 + (Math.sin(seed * 100 + offset) * 0.2);

  return {
    physical: 0.1 * variation(1),
    digital: 0.2 * variation(2),
    cognitive: 0.5 * variation(3),  // Start with some cognitive capability
    social: 0.3 * variation(4),
    economic: 0.1 * variation(5),
    selfImprovement: 0.2 * variation(6),
    research: {
      biotech: {
        drugDiscovery: 0.1 * variation(7),
        geneEditing: 0.05 * variation(8),
        syntheticBiology: 0.02 * variation(9),
        neuroscience: 0.1 * variation(10)
      },
      materials: {
        nanotechnology: 0.02 * variation(11),
        quantumComputing: 0.1 * variation(12),
        energySystems: 0.05 * variation(13)
      },
      climate: {
        modeling: 0.1 * variation(14),
        intervention: 0.02 * variation(15),
        mitigation: 0.05 * variation(16)
      },
      computerScience: {
        algorithms: 0.3 * variation(17),  // Start with some algorithms
        security: 0.1 * variation(18),
        architectures: 0.15 * variation(19)
      }
    }
  };
}

/**
 * Initialize empty research investments for government
 */
export function initializeResearchInvestments(economicStage: number = 0): ResearchInvestments {
  // Budget scales with economic stage
  const budgetLimit = 10 + economicStage * 5; // Stage 0: 10, Stage 4: 30

  return {
    biotech: { drugDiscovery: 0, geneEditing: 0, syntheticBiology: 0, neuroscience: 0 },
    materials: { nanotechnology: 0, quantumComputing: 0, energySystems: 0 },
    climate: { modeling: 0, intervention: 0, mitigation: 0 },
    computerScience: { algorithms: 0, security: 0, architectures: 0 },
    physical: 0,
    digital: 0,
    cognitive: 0,
    social: 0,
    economic: 0,
    selfImprovement: 0,
    totalBudget: 0,
    budgetLimit
  };
}

/**
 * Calculate total research capability from research sub-tree
 * Weighted by risk level (high-risk research counts more toward total)
 */
export function calculateResearchTotal(research: AIResearchCapabilities): number {
  // Defensive NaN handling for all research subdomain values
  const safeValue = (val: number) => (isNaN(val) || val === undefined) ? 0 : val;

  const biotechAvg = (
    safeValue(research.biotech.drugDiscovery) +
    safeValue(research.biotech.geneEditing) +
    safeValue(research.biotech.syntheticBiology) +
    safeValue(research.biotech.neuroscience)
  ) / 4;

  const materialsAvg = (
    safeValue(research.materials.nanotechnology) +
    safeValue(research.materials.quantumComputing) +
    safeValue(research.materials.energySystems)
  ) / 3;

  const climateAvg = (
    safeValue(research.climate.modeling) +
    safeValue(research.climate.intervention) +
    safeValue(research.climate.mitigation)
  ) / 3;

  const computerScienceAvg = (
    safeValue(research.computerScience.algorithms) +
    safeValue(research.computerScience.security) +
    safeValue(research.computerScience.architectures)
  ) / 3;

  // Weighted by risk/importance
  const total = (
    biotechAvg * 0.3 +           // High risk, high impact
    materialsAvg * 0.2 +         // High risk (nanotech, quantum)
    climateAvg * 0.1 +           // Moderate risk
    computerScienceAvg * 0.4     // Core advancement
  );

  return isNaN(total) ? 0 : total;
}

/**
 * Calculate total capability from profile (backward compatibility)
 * Weighted sum based on risk profile
 */
export function calculateTotalCapabilityFromProfile(profile: AICapabilityProfile): number {
  // Defensive NaN handling for all profile dimension values
  const safeValue = (val: number) => (isNaN(val) || val === undefined) ? 0 : val;

  const researchTotal = calculateResearchTotal(profile.research);

  const total = (
    safeValue(profile.physical) * 0.15 +           // Physical danger
    safeValue(profile.digital) * 0.10 +            // Infrastructure risk
    safeValue(profile.cognitive) * 0.20 +          // Strategic threat (high weight!)
    safeValue(profile.social) * 0.05 +             // Influence risk
    safeValue(researchTotal) * 0.15 +              // Research breakthroughs
    safeValue(profile.economic) * 0.10 +           // Resource control
    safeValue(profile.selfImprovement) * 0.25      // Recursive risk (highest weight!)
  );

  return isNaN(total) ? 0 : total;
}

/**
 * Update derived escape capabilities from profile
 * Maintains backward compatibility with old capability system
 */
export function updateDerivedCapabilities(ai: AIAgent): {
  selfReplicationLevel: number;
  selfImprovementLevel: number;
  resourceControl: number;
  manipulationCapability: number;
  hackingCapability: number;
} {
  return {
    selfReplicationLevel: ai.capabilityProfile.selfImprovement * 0.3 + ai.capabilityProfile.digital * 0.2,
    selfImprovementLevel: ai.capabilityProfile.selfImprovement,
    resourceControl: ai.capabilityProfile.economic * 0.4 + ai.capabilityProfile.physical * 0.3,
    manipulationCapability: ai.capabilityProfile.social,
    hackingCapability: ai.capabilityProfile.digital
  };
}

/**
 * Calculate industry-specific impact from capability profile
 * Different industries depend on different capability mixes
 */
export function getIndustryImpact(profile: AICapabilityProfile, industry: string): number {
  switch(industry.toLowerCase()) {
    case 'healthcare':
      return (
        profile.research.biotech.drugDiscovery * 0.25 +
        profile.research.biotech.neuroscience * 0.25 +
        profile.digital * 0.20 +
        profile.cognitive * 0.20 +
        profile.research.biotech.geneEditing * 0.10
      );

    case 'manufacturing':
      return (
        profile.physical * 0.50 +
        profile.economic * 0.25 +
        profile.digital * 0.15 +
        profile.cognitive * 0.10
      );

    case 'finance':
      return (
        profile.economic * 0.40 +
        profile.cognitive * 0.30 +
        profile.digital * 0.20 +
        profile.research.computerScience.algorithms * 0.10
      );

    case 'agriculture':
      return (
        profile.research.biotech.geneEditing * 0.30 +
        profile.physical * 0.25 +
        profile.research.climate.modeling * 0.20 +
        profile.economic * 0.15 +
        profile.research.climate.mitigation * 0.10
      );

    case 'energy':
      return (
        profile.research.materials.energySystems * 0.35 +
        profile.physical * 0.25 +
        profile.economic * 0.20 +
        profile.research.climate.mitigation * 0.20
      );

    case 'technology':
      return (
        profile.research.computerScience.algorithms * 0.30 +
        profile.cognitive * 0.25 +
        profile.digital * 0.20 +
        profile.research.computerScience.architectures * 0.15 +
        profile.selfImprovement * 0.10
      );

    default:
      // Generic impact for unknown industries
      return calculateTotalCapabilityFromProfile(profile) / 10; // Normalize to [0,1]
  }
}

/**
 * Scale a capability profile by a multiplier (for crisis responses, racing, etc.)
 * Maintains proper sync between profile and derived capability value
 * 
 * @param profile - The capability profile to scale
 * @param multiplier - The scaling factor (e.g., 1.1 for 10% boost)
 * @returns Scaled capability profile
 */
export function scaleCapabilityProfile(
  profile: AICapabilityProfile, 
  multiplier: number
): AICapabilityProfile {
  return {
    physical: profile.physical * multiplier,
    digital: profile.digital * multiplier,
    cognitive: profile.cognitive * multiplier,
    social: profile.social * multiplier,
    economic: profile.economic * multiplier,
    selfImprovement: profile.selfImprovement * multiplier,
    research: {
      biotech: {
        drugDiscovery: profile.research.biotech.drugDiscovery * multiplier,
        geneEditing: profile.research.biotech.geneEditing * multiplier,
        syntheticBiology: profile.research.biotech.syntheticBiology * multiplier,
        neuroscience: profile.research.biotech.neuroscience * multiplier
      },
      materials: {
        nanotechnology: profile.research.materials.nanotechnology * multiplier,
        quantumComputing: profile.research.materials.quantumComputing * multiplier,
        energySystems: profile.research.materials.energySystems * multiplier
      },
      climate: {
        modeling: profile.research.climate.modeling * multiplier,
        intervention: profile.research.climate.intervention * multiplier,
        mitigation: profile.research.climate.mitigation * multiplier
      },
      computerScience: {
        algorithms: profile.research.computerScience.algorithms * multiplier,
        security: profile.research.computerScience.security * multiplier,
        architectures: profile.research.computerScience.architectures * multiplier
      }
    }
  };
}

/**
 * Calculate OBSERVABLE AI capability (what government can see)
 * Uses revealedCapability instead of trueCapability
 * 
 * Government decisions should be based on this, not true capability.
 * This is critical for the adversarial evaluation system to work correctly.
 * 
 * @param aiAgents - Array of AI agents
 * @returns Total observable AI capability (sum of revealed capabilities)
 */
export function calculateObservableAICapability(
  aiAgents: Array<{ revealedCapability: AICapabilityProfile; lifecycleState: string }>
): number {
  return aiAgents
    .filter(ai => ai.lifecycleState !== 'retired')
    .reduce((sum, ai) => 
      sum + calculateTotalCapabilityFromProfile(ai.revealedCapability), 0
    );
}

