/**
 * ComputeGrowthPhase (5.0)
 *
 * Applies Moore's Law and algorithmic improvements to compute infrastructure.
 * This must run BEFORE allocation so efficiency multipliers are applied.
 *
 * **EXECUTION ORDER:** 5.0 (Very early, first in simulation step)
 * **DEPENDENCIES:** Requires compute infrastructure
 * **SIDE EFFECTS:**
 * - Updates compute efficiency multipliers
 * - Applies algorithmic progress
 */

import { SimulationPhase, PhaseResult } from '../PhaseOrchestrator';
import { GameState } from '@/types/game';
import { RNGFunction } from '@/types/rng';

export class ComputeGrowthPhase implements SimulationPhase {
  readonly id = 'compute-growth';
  readonly name = 'Compute Growth (Moore\'s Law)';
  readonly order = 1.0;

  execute(state: GameState, rng: RNGFunction): PhaseResult {
    // Import and execute compute growth
    const { applyComputeGrowth } = require('../../computeInfrastructure');

    applyComputeGrowth(state, rng);

    // No events generated by growth
    return { events: [] };
  }
}

/**
 * Compute Infrastructure Module
 * Phase 1: Data Center Infrastructure
 * 
 * Manages data centers, compute allocation, and related utilities.
 */

import { ComputeInfrastructure, DataCenter, GameState } from '../types/game';

/**
 * Initialize compute infrastructure for January 2025
 * Based on real-world AI infrastructure landscape
 */
export function initializeComputeInfrastructure(): ComputeInfrastructure {
  return {
    dataCenters: [
      // OpenAI / Microsoft
      {
        id: 'openai_sf',
        name: 'OpenAI San Francisco',
        organizationId: 'openai', // Will be linked in Phase 2
        capacity: 150, // ~150 PetaFLOPs
        efficiency: 1.05,
        constructionMonth: -12, // Built 12 months before game start
        completionMonth: -12,
        operational: true,
        operationalCost: 2.25, // $2.25M/month equivalent
        restrictedAccess: true,
        allowedAIs: [], // Will be populated when AIs are linked to orgs
        region: 'US'
      },

      // Google DeepMind
      {
        id: 'google_iowa',
        name: 'Google Iowa Data Center',
        organizationId: 'google_deepmind', // Phase 2
        capacity: 200,
        efficiency: 1.1, // Google is very efficient
        constructionMonth: -24,
        completionMonth: -24,
        operational: true,
        operationalCost: 3.0,
        restrictedAccess: true,
        allowedAIs: [],
        region: 'US'
      },

      // Meta AI (open weights!)
      {
