  tippingPointCascadeMonths: number;

  // === REGIONAL INEQUALITY (Oct 12, 2025) ===
  qolGiniCoefficient: number;         // QoL inequality (0=equal, 1=extreme)
  qolTopRegion: number;               // Best-off region's QoL
